(() => {
  const game = window.DRIFTWING;
  if (!game.debug) throw new Error('high-altitude needs the dev hooks (a dev server, or a build with ?debug=1)');
  const { ctx, state } = game;
  const flight = ctx.systems.flight;
  const sky = ctx.systems.sky;
  const farField = ctx.systems.farField;
  const terrain = ctx.systems.terrain;
  const THREE = ctx.THREE;
  const results = [];
  const check = (name, ok, detail) => {
    results.push(name);
    if (!ok) console.error('[high-altitude check] ' + name + ' failed: ' + detail);
    return (ok ? 'PASS ' : 'FAIL ') + name + ': ' + detail;
  };
  const originalCeiling = flight.getCeiling;
  // The test climbs with the glider: lift the loop's safety-net ceiling for it (the spaceplane's own
  // limits.ceiling does this in flight). The frames are stepped by hand with the clock paused, so the
  // flight model never ticks and only the safety net reads the ceiling.
  flight.getCeiling = () => 150000;
  game.debug.pauseLoop();
  state.paused = true;
  const spawn = state.spawn;
  ctx.systems.sky.setDayTime(ctx.util.dayTimeForSunElevation(ctx.CONFIG.START_SUN_ELEVATION_DEG, true), { transition: 0 });
  const target = new THREE.RenderTarget(320, 180, { type: THREE.UnsignedByteType });
  const magenta = new THREE.Color(1, 0, 1);
  const pose = { position: new THREE.Vector3(), quaternion: new THREE.Quaternion(), euler: new THREE.Euler(0, 0, 0, 'YXZ') };
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  function at(altitude, frames = 24) {
    flight.resetTo({ x: spawn.x, y: altitude, z: spawn.z, heading: spawn.heading });
    game.debug.stepFrames(frames);
  }
  function shell() {
    return ctx.scene.getObjectByName('far-field-cloud-shell');
  }
  /** Points the camera from the craft: pitch (deg, negative down) along the spawn heading. */
  function applyPose(pitch) {
    pose.position.copy(state.player.position);
    pose.euler.set(pitch * Math.PI / 180, -spawn.heading * Math.PI / 180, 0, 'YXZ');
    pose.quaternion.setFromEuler(pose.euler);
    ctx.camera.position.copy(pose.position);
    ctx.camera.quaternion.copy(pose.quaternion);
    ctx.camera.updateMatrixWorld();
  }
  /** Steps frames until the far field and the terrain have built what this view needs (or the time runs out). */
  async function settle(pitch, limitMs = 90000) {
    const started = performance.now();
    let stats = null;
    while (performance.now() - started < limitMs) {
      game.debug.stepFrames(2);
      if (pitch !== null) {
        applyPose(pitch);
        terrain.update(0, 1 / 60);
        farField.update(0, 1 / 60);
        sky.update(0, 0);
      }
      stats = farField.getStats();
      const terrainStats = terrain.getStats();
      const farReady = !stats.active || (stats.holes === 0 && stats.pending === 0);
      if (farReady && (terrainStats.high.hidden || terrainStats.pending === 0)) return { stats, waitedMs: Math.round(performance.now() - started) };
      await sleep(200);
    }
    return { stats, waitedMs: Math.round(performance.now() - started), timedOut: true };
  }
  /** Renders the scene (sky dome off, magenta background, cloud shell off) and counts magenta pixels. */
  async function probe() {
    const dome = sky.dome;
    const background = ctx.scene.background;
    const cloudShell = shell();
    const shellVisible = cloudShell ? cloudShell.visible : false;
    dome.visible = false;
    if (cloudShell) cloudShell.visible = false;
    ctx.scene.background = magenta;
    ctx.renderer.setRenderTarget(target);
    ctx.renderer.render(ctx.scene, ctx.camera);
    ctx.renderer.setRenderTarget(null);
    const pixels = await ctx.renderer.readRenderTargetPixelsAsync(target, 0, 0, target.width, target.height);
    dome.visible = true;
    if (cloudShell) cloudShell.visible = shellVisible;
    ctx.scene.background = background;
    let holes = 0;
    let red = 0;
    let green = 0;
    let blue = 0;
    const count = target.width * target.height;
    for (let index = 0; index < count; index++) {
      const r = pixels[index * 4];
      const g = pixels[index * 4 + 1];
      const b = pixels[index * 4 + 2];
      if (r > 180 && b > 180 && g < 40) holes++;
      red += r;
      green += g;
      blue += b;
    }
    return { holes, pixels: count, mean: [red / count, green / count, blue / count] };
  }
  function atmosphere() {
    const a = state.atmosphere;
    return { altitude: Math.round(a.altitude), darkness: +a.skyDarkness.toFixed(3), stars: +a.starVisibility.toFixed(3), limb: +a.limb.toFixed(3), sharpness: +a.sunSharpness.toFixed(3), curvature: +a.curvature.toFixed(3), haze: +a.hazeBlend.toFixed(3), handoff: +a.handoff.toFixed(3), horizonKm: Math.round(a.horizonDistance / 1000), viewKm: Math.round(a.viewDistance / 1000), far: Math.round(ctx.camera.far), near: ctx.camera.near };
  }
  function restore() {
    flight.getCeiling = originalCeiling;
    target.dispose();
  }
  window.__dwHA = { game, ctx, state, check, at, applyPose, settle, probe, atmosphere, restore, results, means: {} };
  return 'high-altitude helpers ready, ceiling lifted for the test, loop paused';
})()

(async () => {
    const h = window.__dwHA;
    const samples = [];
    let worstHoles = 0;
    for (let altitude = 10800; altitude <= 13200; altitude += 200) {
      h.at(altitude, 6);
      const settled = await h.settle(-55, 60000);
      const result = await h.probe();
      worstHoles = Math.max(worstHoles, result.holes);
      samples.push({ altitude, mean: result.mean.map((value) => +value.toFixed(2)), holes: result.holes, timedOut: Boolean(settled.timedOut) });
    }
    let worstStep = 0;
    for (let index = 1; index < samples.length; index++) {
      const previous = samples[index - 1].mean;
      const current = samples[index].mean;
      worstStep = Math.max(worstStep, Math.abs(current[0] - previous[0]), Math.abs(current[1] - previous[1]), Math.abs(current[2] - previous[2]));
    }
    return h.check('the 11-13 km handoff band is steady and has no holes', worstHoles === 0 && worstStep < 6 && samples.every((sample) => !sample.timedOut), JSON.stringify({ worstStepLevels: +worstStep.toFixed(2), worstHoles, samples }));
  })()
